/*
 * db.ts - the bundled remote database, and identifying a remote from one press.
 *
 * Generated by tools/db-build/build-db.mjs from Flipper-IRDB (CC0-1.0). The
 * index is loaded once; the button maps are sharded and fetched only for the
 * remote the user actually picks.
 */
import { IrProtocol, encodeKey, makeKey } from './irProtocol';
import { buttonIdFor, type RemoteButton, type RemoteProfile, newId } from './types';

export interface DbRemote {
  i: number; // index, also the id
  b: string; // brand
  m: string; // model
  c: string; // category
  p: number; // ir_protocol_t
  a: number; // address
  n: number; // button count
  s: number; // shard
}

export interface DbIndex {
  source: string;
  sourceUrl: string;
  license: string;
  generated: string;
  shards: number;
  remotes: DbRemote[];
  lookup: Record<string, number[]>;
}

/** [name, command] or [name, command, canonicalName] */
export type DbButton = [string, number] | [string, number, string];

let indexPromise: Promise<DbIndex> | null = null;
const shardCache = new Map<number, Record<string, DbButton[]>>();

export function loadIndex(): Promise<DbIndex> {
  if (!indexPromise) {
    indexPromise = fetch('./db/index.json')
      .then((r) => {
        if (!r.ok) throw new Error(`database index missing (HTTP ${r.status})`);
        return r.json();
      })
      .catch((e) => {
        indexPromise = null;
        throw e;
      });
  }
  return indexPromise;
}

async function loadShard(n: number): Promise<Record<string, DbButton[]>> {
  const cached = shardCache.get(n);
  if (cached) return cached;
  const r = await fetch(`./db/buttons/${String(n).padStart(2, '0')}.json`);
  if (!r.ok) throw new Error(`database shard ${n} missing (HTTP ${r.status})`);
  const data = (await r.json()) as Record<string, DbButton[]>;
  shardCache.set(n, data);
  return data;
}

export async function loadButtons(remote: DbRemote): Promise<DbButton[]> {
  const shard = await loadShard(remote.s);
  return shard[String(remote.i)] ?? [];
}

/**
 * Candidate remotes for a decoded frame.
 *
 * Matching is on protocol plus address, which is what a remote actually
 * shares across all its buttons. It narrows thousands of remotes to a
 * handful, but it cannot be exact: many manufacturers ship dozens of models
 * on one address. The UI presents these as suggestions to confirm, never as a
 * definitive answer, and the layout stays editable afterwards.
 */
export async function identify(protocol: number, address: number): Promise<DbRemote[]> {
  const idx = await loadIndex();
  const ids = idx.lookup[`${protocol}:${address}`] ?? [];
  return ids.map((i) => idx.remotes[i]).filter(Boolean);
}

export async function searchRemotes(query: string, limit = 60): Promise<DbRemote[]> {
  const idx = await loadIndex();
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const terms = q.split(/\s+/);
  const out: DbRemote[] = [];
  for (const r of idx.remotes) {
    const hay = `${r.b} ${r.m} ${r.c}`.toLowerCase();
    if (terms.every((t) => hay.includes(t))) {
      out.push(r);
      if (out.length >= limit) break;
    }
  }
  return out;
}

/**
 * Build an editable profile from a database entry. Every button arrives with
 * its IR code already known, so nothing needs learning -- but each one can
 * still be renamed, moved, re-learned or deleted if the entry is wrong for
 * the user's actual remote.
 */
export async function profileFromDb(remote: DbRemote): Promise<RemoteProfile> {
  const raw = await loadButtons(remote);
  const taken = new Set<string>();
  const COLS = 4;

  const buttons: RemoteButton[] = raw.map(([name, cmd, canon], n) => ({
    id: buttonIdFor(canon ?? name, taken),
    label: prettify(name),
    canon,
    row: Math.floor(n / COLS),
    col: n % COLS,
    key: encodeKey(makeKey(remote.p, remote.a, cmd)),
  }));

  return {
    id: newId('profile'),
    name: `${remote.b} ${remote.m}`.trim(),
    brand: remote.b,
    model: remote.m,
    protocol: remote.p,
    address: remote.a,
    source: 'database',
    dbIndex: remote.i,
    buttons,
    updated: new Date().toISOString(),
  };
}

/** "Vol_up" -> "Vol Up"; database names are terse and inconsistent. */
export function prettify(name: string): string {
  return name
    .replace(/[_]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

export function protocolIsDecoded(p: number, mask: number): boolean {
  return p === IrProtocol.RawHash || (mask & (1 << p)) !== 0;
}
